const input = $input.first().json;
const body = input.body ?? input;
const data = body.data ?? {};
const key = data.key ?? {};
const message = data.message ?? {};

const instance = String(body.instance ?? '');
const remoteJid = String(key.remoteJid ?? '');
const fromMe = key.fromMe === true;
const isGroup = remoteJid.endsWith('@g.us');

const text = String(
  message.conversation ??
  message.extendedTextMessage?.text ??
  ''
).trim();

let messageType = 'other';

if (text) {
  messageType = 'text';
} else if (
  message.audioMessage ||
  message.pttMessage
) {
  messageType = 'audio';
} else if (message.imageMessage) {
  messageType = 'image';
} else if (message.videoMessage) {
  messageType = 'video';
} else if (message.documentMessage) {
  messageType = 'document';
} else if (message.stickerMessage) {
  messageType = 'sticker';
}

const expectedInstance = 'domo-atendimento';
const TIME_ZONE = 'America/Bahia';

const formatter = new Intl.DateTimeFormat(
  'en-CA',
  {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }
);

const parts = Object.fromEntries(
  formatter
    .formatToParts(new Date())
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value])
);

const localDate =
  `${parts.year}-${parts.month}-${parts.day}`;

const localHour = Number(parts.hour);
const localMinute = Number(parts.minute);

const easterSunday = year => {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l =
    (32 + 2 * e + 2 * i - h - k) % 7;
  const m =
    Math.floor((a + 11 * h + 22 * l) / 451);

  const month =
    Math.floor((h + l - 7 * m + 114) / 31);

  const day =
    ((h + l - 7 * m + 114) % 31) + 1;

  return new Date(
    Date.UTC(year, month - 1, day, 12, 0, 0)
  );
};

const formatBahiaDate = date => {
  const p = Object.fromEntries(
    formatter
      .formatToParts(date)
      .filter(part => part.type !== 'literal')
      .map(part => [part.type, part.value])
  );

  return `${p.year}-${p.month}-${p.day}`;
};

const addDays = (date, days) =>
  new Date(
    date.getTime() + days * 86400000
  );

const year = Number(parts.year);
const easter = easterSunday(year);

const goodFriday =
  formatBahiaDate(addDays(easter, -2));

const corpusChristi =
  formatBahiaDate(addDays(easter, 60));

const holidays = new Set([
  `${parts.year}-01-01`,
  goodFriday,
  `${parts.year}-04-21`,
  `${parts.year}-05-01`,
  corpusChristi,

  // Salvador
  `${parts.year}-06-24`,

  // Bahia
  `${parts.year}-07-02`,

  `${parts.year}-09-07`,
  `${parts.year}-10-12`,
  `${parts.year}-11-02`,
  `${parts.year}-11-15`,
  `${parts.year}-11-20`,

  // Salvador
  `${parts.year}-12-08`,

  `${parts.year}-12-25`,
]);

const isHoliday = holidays.has(localDate);

const isWeekend =
  parts.weekday === 'Sat' ||
  parts.weekday === 'Sun';

const isProgramWindow =
  !isWeekend &&
  !isHoliday &&
  localHour === 21;

const correctInstance =
  instance === expectedInstance;

const state =
  $getWorkflowStaticData('global');

state.customerSessions ??= {};
state.processedMessages ??= {};

const messageId = String(key.id ?? '');
const dedupKey =
  `${instance}:${messageId}`;

const nowMs = Date.now();
const DEDUP_TTL_MS = 15 * 60 * 1000;

for (const [id, timestamp] of Object.entries(
  state.processedMessages
)) {
  if (
    typeof timestamp !== 'number' ||
    nowMs - timestamp > DEDUP_TTL_MS
  ) {
    delete state.processedMessages[id];
  }
}

const duplicated =
  Boolean(
    messageId &&
    state.processedMessages[dedupKey]
  );

if (
  correctInstance &&
  messageId &&
  !duplicated
) {
  state.processedMessages[dedupKey] =
    nowMs;
}

const shouldRespond =
  correctInstance &&
  !duplicated &&
  !fromMe &&
  !isGroup &&
  messageType === 'text' &&
  text.length > 0 &&
  !isProgramWindow;

const sessionKey =
  `${instance}:${remoteJid}`;

const SESSION_MINUTES = 30;
const ttl =
  SESSION_MINUTES * 60 * 1000;

const current =
  state.customerSessions[sessionKey];

const hasActiveSession =
  Boolean(
    current?.lastSeen &&
    Date.now() - current.lastSeen < ttl
  );

const firstInteraction =
  !hasActiveSession;

const history =
  Array.isArray(current?.history)
    ? current.history.slice(-10)
    : [];

if (shouldRespond) {
  state.customerSessions[sessionKey] = {
    lastSeen: Date.now(),
    history,
  };
}

return [{
  json: {
    shouldRespond,

    reason:
      !correctInstance
        ? 'wrong_instance'
        : duplicated
          ? 'duplicate'
          : fromMe
          ? 'from_me'
          : isGroup
            ? 'group'
            : messageType !== 'text'
              ? 'non_text'
              : isProgramWindow
                ? 'live_program'
                : 'text_allowed',

    instance,
    remoteJid,
    number: remoteJid.split('@')[0],
    messageId,
    duplicated,

    messageType,
    text,
    firstInteraction,
    history,

    isHoliday,
    isWeekend,
    isProgramWindow,

    localDate,
    localTime:
      String(localHour).padStart(2, '0') +
      ':' +
      String(localMinute).padStart(2, '0'),
  }
}];

const response = $input.first().json;

const context =
  $('Preparar atendimento').item.json;

const silent =
  response.assistant?.silent === true;

const temporarilyUnavailable =
  response.status === 'temporarily_unavailable';

const answer = String(
  response.assistant?.answer ?? ''
).trim();

if (
  !answer &&
  !silent &&
  !temporarilyUnavailable
) {
  return [];
}

const state =
  $getWorkflowStaticData('global');

state.customerSessions ??= {};
state.customerFallbacks ??= {};

const sessionKey =
  `${context.instance}:${context.remoteJid}`;

if (temporarilyUnavailable) {
  const now = Date.now();

  const FALLBACK_COOLDOWN_MS =
    10 * 60 * 1000;

  const lastFallback =
    Number(
      state.customerFallbacks[sessionKey] ?? 0
    );

  if (
    lastFallback > 0 &&
    now - lastFallback < FALLBACK_COOLDOWN_MS
  ) {
    return [];
  }

  state.customerFallbacks[sessionKey] =
    now;
}

const current =
  state.customerSessions[sessionKey] ?? {
    history: [],
  };

const history =
  Array.isArray(current.history)
    ? current.history
    : [];

history.push({
  role: 'user',
  text: String(context.text).slice(0, 2000),
});

if (
  !silent &&
  answer
) {
  history.push({
    role: 'assistant',
    text: answer.slice(0, 2000),
  });
}

state.customerSessions[sessionKey] = {
  lastSeen: Date.now(),
  history: history.slice(-10),
};

if (silent) {
  return [];
}

if (!answer) {
  return [];
}

return [{
  json: {
    number: context.number,
    text: answer,
  }
}];

const input = $input.first().json;

const raw = String(
  input.text ?? ''
)
  .replace(/\\s*\\n+\\s*/g, '\\n')
  .trim();

if (!raw) {
  return [];
}

const limit = 3500;

const text =
  raw.length > limit
    ? raw.slice(0, limit - 80).trimEnd() +
      '…\\n\\nResposta limitada para envio seguro pelo WhatsApp.'
    : raw;

return [{
  json: {
    number: input.number,
    text,
  }
}];
